#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret names set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  local opener=""
  if   command -v wslview      >/dev/null 2>&1; then opener="wslview"
  elif command -v explorer.exe >/dev/null 2>&1; then opener="explorer.exe"
  elif { [[ "${OSTYPE:-}" == darwin* ]] || [ "$(uname -s 2>/dev/null)" = "Darwin" ]; } && command -v open >/dev/null 2>&1; then opener="open"
  elif [ -n "${DISPLAY:-}" ] || [ -n "${WAYLAND_DISPLAY:-}" ]; then
    if   command -v xdg-open >/dev/null 2>&1; then opener="xdg-open"
    elif command -v open     >/dev/null 2>&1; then opener="open"
    fi
  fi

  if [ -n "$opener" ]; then
    printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
    "$opener" "$url" </dev/null >/dev/null 2>&1 &
  else
    warn "couldn't open a browser; visit it manually: $url"
  fi
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4

banner "Release-Please GitHub App Credential Setup"

# ── Stage 1: Register Repository-Scoped GitHub App ────────────────────────
stage "GitHub App: Register Repository-Scoped App"
say "Automated Release (.github/workflows/release-please.yml) mints a short-lived"
say "GitHub App installation token so Release PR updates trigger CI checks and"
say "Release PR merges push package tags that start release.yml."
open_url "https://github.com/settings/apps/new"
step "Fill in the new GitHub App registration form:"
step "  • GitHub App name:  imednet-toolkit-release-bot (or another unique name)"
step "  • Homepage URL:     https://github.com/fderuiter/imednet-toolkit"
step "  • Webhook:          Uncheck 'Active' (no webhook events are required)"
step "Under 'Permissions -> Repository permissions', grant ONLY:"
step "  • Contents:         Read and write"
step "  • Issues:           Read and write"
step "  • Pull requests:    Read and write"
step "Under 'Where can this GitHub App be installed?', choose 'Only on this account'."
step "Click 'Create GitHub App'."
pause "Press Enter once the GitHub App is created..."

# ── Stage 2: Store GitHub App ID Secret ───────────────────────────────────
stage "GitHub Secret: RELEASE_PLEASE_APP_ID"
say "On the GitHub App 'General' settings page, locate the numeric 'App ID' near the top."
ask_secret RELEASE_PLEASE_APP_ID "Paste the GitHub App ID:"
if [[ -n "$RELEASE_PLEASE_APP_ID" ]]; then
  set_secret RELEASE_PLEASE_APP_ID "$RELEASE_PLEASE_APP_ID"
else
  SKIPPED+=("GitHub secret RELEASE_PLEASE_APP_ID (set it manually: gh secret set RELEASE_PLEASE_APP_ID)")
  warn "RELEASE_PLEASE_APP_ID was left blank; set it manually before running Automated Release."
fi

# ── Stage 3: Generate & Store Private Key Secret ──────────────────────────
stage "GitHub Secret: RELEASE_PLEASE_PRIVATE_KEY"
say "On the same GitHub App 'General' settings page, scroll to 'Private keys'."
step "Click 'Generate a private key'. GitHub downloads a .pem file to your computer."
ask PEM_FILE_PATH "Enter path to the downloaded .pem file (or leave blank to paste manually):"

PEM_FILE_PATH="${PEM_FILE_PATH#\"}"
PEM_FILE_PATH="${PEM_FILE_PATH%\"}"
PEM_FILE_PATH="${PEM_FILE_PATH#\'}"
PEM_FILE_PATH="${PEM_FILE_PATH%\'}"
if [[ "$PEM_FILE_PATH" == "~/"* ]]; then
  PEM_FILE_PATH="${HOME}/${PEM_FILE_PATH#~/}"
fi

RELEASE_PLEASE_PRIVATE_KEY=""
if [[ -n "$PEM_FILE_PATH" ]]; then
  if [[ -f "$PEM_FILE_PATH" ]]; then
    RELEASE_PLEASE_PRIVATE_KEY="$(cat "$PEM_FILE_PATH")"
  else
    warn "File not found at '$PEM_FILE_PATH'."
  fi
fi

if [[ -z "$RELEASE_PLEASE_PRIVATE_KEY" ]]; then
  note "Paste the full PEM private key contents, then press Ctrl-D on an empty line:"
  RELEASE_PLEASE_PRIVATE_KEY="$(cat || true)"
fi

if [[ -n "$RELEASE_PLEASE_PRIVATE_KEY" ]]; then
  set_secret RELEASE_PLEASE_PRIVATE_KEY "$RELEASE_PLEASE_PRIVATE_KEY"
  if [[ -n "$PEM_FILE_PATH" && -f "$PEM_FILE_PATH" ]]; then
    if confirm "Delete the local downloaded key file ($PEM_FILE_PATH) now?"; then
      rm -f "$PEM_FILE_PATH"
      say "✓ Removed local .pem file."
    fi
  fi
else
  SKIPPED+=("GitHub secret RELEASE_PLEASE_PRIVATE_KEY (set it manually: gh secret set RELEASE_PLEASE_PRIVATE_KEY < app-key.pem)")
  warn "RELEASE_PLEASE_PRIVATE_KEY was empty; set it manually before running Automated Release."
fi

# ── Stage 4: Install GitHub App on Repository ─────────────────────────────
stage "GitHub App: Install on imednet-toolkit"
say "Install the GitHub App on this repository only so installation tokens stay scoped."
open_url "https://github.com/settings/apps"
step "Select your newly created GitHub App, then click 'Install App' in the left sidebar."
step "Click 'Install' next to your account (fderuiter)."
step "Choose 'Only select repositories' and select 'fderuiter/imednet-toolkit'."
step "Click 'Install'."
pause "Press Enter once the GitHub App is installed on fderuiter/imednet-toolkit..."

finish
